use std::collections::BTreeMap;
use std::fs::{create_dir_all, write};
use std::io::{Error as IoError, ErrorKind};
use std::mem::replace;
use std::path::Path;
use std::str::FromStr;

use proc_macro2::{Ident as Ident2, TokenStream};
use quote::{format_ident, quote, ToTokens};

use super::IdentPath;

/// Manages the code that is generated for a specific module.
///
/// This type stores the generated code, the related using directives as well as
/// any sub-module for a specific module generated by the code generator.
#[derive(Default, Debug)]
pub struct Module {
    /// The actual code that is manages by this module.
    pub code: TokenStream,

    /// A set of using directives this module needs.
    pub usings: BTreeMap<String, bool>,

    /// A map of sub-modules contained inside this module.
    pub modules: BTreeMap<String, Module>,

    /// Public items re-exported from this module when using type modules.
    pub exports: BTreeMap<String, Ident2>,
}

/// Defines how the sub modules of the [`Module`] will be generated when calling
/// [`Module::to_code()`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SubModules {
    /// No code is generated for any sub-module.
    None,

    /// The sub-modules are references as separate files.
    ///
    /// This will generate something like this:
    ///
    /// ```rust,ignore
    /// pub mod sub_module;
    /// pub mod another_module;
    ///
    /// // Actual module code
    /// ```
    Files,

    /// The sub-modules are generated as inline modules.
    ///
    /// This will generate something like this:
    ///
    /// ```rust,ignore
    /// // Actual module code
    ///
    /// pub mod sub_module {
    ///     // Sub-Module Code
    /// }
    ///
    /// pub mod another_module {
    ///     // Sub-Module Code
    /// }
    /// ```
    Inline,
}

/// Formatting applied when converting generated code to source text.
#[derive(Default, Debug, Clone, Copy, PartialEq, Eq)]
pub enum CodeFormat {
    /// Use the token stream's unformatted representation (the default).
    #[default]
    Plain,

    /// Format Rust source using `prettyplease`, enabled by the `pretty` feature.
    Pretty,
}

impl Module {
    /// Append the passed `code` to this module code.
    pub fn append(&mut self, code: TokenStream) -> &mut Self {
        self.code.extend(code);

        self
    }

    /// Register a public item for re-export from the containing namespace or schema.
    ///
    /// Custom render steps that emit public items into a type module should call
    /// this method for each item that also needs to be accessible from its parent.
    pub fn export(&mut self, ident: &Ident2) -> &mut Self {
        self.exports.insert(ident.to_string(), ident.clone());
        self
    }

    /// Prepend the passed `code` to this module code.
    pub fn prepend(&mut self, code: TokenStream) -> &mut Self {
        let code = replace(&mut self.code, code);

        self.append(code)
    }

    /// Add using directives to the set of this module.
    pub fn usings<I>(&mut self, anonymous: bool, usings: I) -> &mut Self
    where
        I: IntoIterator,
        I::Item: ToString,
    {
        for using in usings {
            *self.usings.entry(using.to_string()).or_insert(anonymous) &= anonymous;
        }

        self
    }

    /// Get a reference to a sub-module identified by the passed `ident`.
    ///
    /// If the module does not exist `None` is returned.
    pub fn module<T>(&self, ident: T) -> Option<&Module>
    where
        T: AsRef<str>,
    {
        self.modules.get(ident.as_ref())
    }

    /// Get a mutable reference to a sub-module identified by the passed `ident`.
    ///
    /// If the module does not exist it will be created.
    pub fn module_mut<T>(&mut self, ident: T) -> &mut Module
    where
        T: Into<String>,
    {
        self.modules.entry(ident.into()).or_default()
    }

    /// Write the module to the passed `token` stream.
    ///
    /// This method writes the current module to the passed `token` stream. The
    /// `sub_modules` parameter defines how the sub-modules of this module will
    /// be rendered.
    pub fn to_code(&self, tokens: &mut TokenStream, sub_modules: SubModules) {
        let Self {
            code,
            usings,
            modules,
            ..
        } = self;

        if sub_modules == SubModules::Files {
            let modules = modules.keys().map(|ident| {
                let name = format_ident!("{ident}");

                quote!(pub mod #name;)
            });

            tokens.extend(quote! {
                #( #modules )*
            });
        }

        let usings = render_usings(usings.iter());

        tokens.extend(quote! {
            #usings
            #code
        });

        if sub_modules == SubModules::Inline {
            for (ident, module) in modules {
                let name = format_ident!("{ident}");

                tokens.extend(quote! {
                    pub mod #name {
                        #module
                    }
                });
            }
        }
    }

    /// Convert this module to Rust source with the selected formatting.
    ///
    /// Use [`SubModules::Inline`] for single-file output or [`SubModules::Files`]
    /// when writing each module separately. Formatting is applied to the final
    /// source text; token streams returned by [`crate::generate`] retain their
    /// usual representation.
    ///
    /// # Errors
    /// Returns [`crate::Error::FormattingError`] if the generated code is not a
    /// valid Rust file, or if [`CodeFormat::Pretty`] is selected without the
    /// `pretty` feature.
    pub fn to_code_with_format(
        &self,
        sub_modules: SubModules,
        format: CodeFormat,
    ) -> Result<String, crate::Error> {
        let mut code = TokenStream::new();
        self.to_code(&mut code, sub_modules);

        match format {
            CodeFormat::Plain => Ok(code.to_string()),
            CodeFormat::Pretty => {
                #[cfg(feature = "pretty")]
                {
                    syn::parse2(code)
                        .map(|syntax| prettyplease::unparse(&syntax))
                        .map_err(|error| crate::Error::FormattingError(error.to_string()))
                }
                #[cfg(not(feature = "pretty"))]
                {
                    Err(crate::Error::FormattingError(
                        "the pretty feature is not enabled".into(),
                    ))
                }
            }
        }
    }

    /// Write the code of the current module to the passed `directory`.
    ///
    /// This will split up the current module into it's sub modules and
    /// writes them to the passed `directory`. Each sub-module is written to
    /// it's own module file.
    ///
    /// # Errors
    /// Returns an [`IoError`] if writing a module to a file failed.
    pub fn write_to_files<P>(&self, directory: P) -> Result<(), IoError>
    where
        P: AsRef<Path>,
    {
        self.write_to_files_with_format(directory, CodeFormat::Plain)
            .map_err(|error| match error {
                crate::Error::IoError(error) => error,
                error => IoError::new(ErrorKind::InvalidData, error),
            })
    }

    /// Write each module to a separate file with the selected formatting.
    ///
    /// Like [`write_to_files`](Self::write_to_files), with explicit control over
    /// formatting. `CodeFormat::Pretty` formats every file using `prettyplease` with the
    /// `pretty` feature enabled.
    ///
    /// # Errors
    /// Returns [`crate::Error::IoError`] if writing fails, or
    /// [`crate::Error::FormattingError`] if formatting fails or the `pretty`
    /// feature is not enabled when selecting [`CodeFormat::Pretty`].
    pub fn write_to_files_with_format<P>(
        &self,
        directory: P,
        format: CodeFormat,
    ) -> Result<(), crate::Error>
    where
        P: AsRef<Path>,
    {
        let directory = directory.as_ref();

        self.write_to_files_with(|module: &Module, path: &Path| {
            let filename = if module.modules.is_empty() {
                directory.join(path).with_extension("rs")
            } else {
                directory.join(path).join("mod.rs")
            };
            if let Some(parent) = filename.parent() {
                create_dir_all(parent)?;
            }

            let code = module.to_code_with_format(SubModules::Files, format)?;
            write(filename, code)?;

            Ok(())
        })
    }

    /// Write the code of the different sub-modules by using the passed
    /// function `f`.
    ///
    /// This will split up the current module into it's sub modules and
    /// passes the generated code for each module to the passed function `f`.
    ///
    /// # Errors
    /// Forwards the error raised by `f`.
    pub fn write_to_files_with<F, E>(&self, mut f: F) -> Result<(), E>
    where
        F: FnMut(&Module, &Path) -> Result<(), E>,
    {
        self.write_to_files_with_impl("", &mut f)
    }

    fn write_to_files_with_impl<P, F, E>(&self, path: P, f: &mut F) -> Result<(), E>
    where
        P: AsRef<Path>,
        F: FnMut(&Module, &Path) -> Result<(), E>,
    {
        let path = path.as_ref();

        f(self, path)?;

        for (ident, module) in &self.modules {
            let path = path.join(ident);

            module.write_to_files_with_impl(path, f)?;
        }

        Ok(())
    }
}

impl ToTokens for Module {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        self.to_code(tokens, SubModules::Inline);
    }
}

fn render_usings<'x, I, X>(usings: I) -> TokenStream
where
    I: IntoIterator<Item = (X, &'x bool)>,
    X: AsRef<str>,
{
    #[derive(Default)]
    struct Module {
        usings: BTreeMap<Ident2, bool>,
        sub_modules: BTreeMap<Ident2, Module>,
    }

    impl Module {
        fn render(&self) -> TokenStream {
            let count = self.usings.len() + self.sub_modules.len();

            let usings = self.usings.iter().map(|(ident, anonymous)| {
                if *anonymous {
                    quote!(#ident as _)
                } else {
                    quote!(#ident)
                }
            });
            let sub_modules = self.sub_modules.iter().map(|(ident, module)| {
                let using = module.render();

                quote!(#ident::#using)
            });

            let items = usings.chain(sub_modules);

            if count > 1 {
                quote!({ #( #items ),* })
            } else {
                quote!(#( #items )*)
            }
        }
    }

    let mut root = Module::default();

    for (using, anonymous) in usings {
        let using = using.as_ref();
        let Ok(ident) = IdentPath::from_str(using) else {
            continue;
        };

        let (ident, path, _) = ident.into_parts();

        let mut module = &mut root;
        for part in path.into_iter().flat_map(|x| x.0) {
            module = module.sub_modules.entry(part).or_default();
        }

        *module.usings.entry(ident).or_insert(*anonymous) &= *anonymous;
    }

    let mut ret = TokenStream::new();
    for (ident, module) in &root.sub_modules {
        let using = module.render();
        ret.extend(quote!(use #ident::#using;));
    }

    ret
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_format_is_the_default() {
        assert_eq!(CodeFormat::default(), CodeFormat::Plain);
        let mut module = Module::default();
        module.append(quote!(
            pub struct Example;
        ));
        assert_eq!(
            module
                .to_code_with_format(SubModules::Inline, CodeFormat::Plain)
                .unwrap(),
            quote!(
                pub struct Example;
            )
            .to_string(),
        );
    }

    #[test]
    fn formatting_entry_points_return_the_same_error() {
        let mut module = Module::default();
        module.append(quote!(pub struct));
        module.module_mut("child");
        let directory =
            std::env::temp_dir().join(format!("xsd-parser-format-errors-{}", std::process::id()));
        let inline = module.to_code_with_format(SubModules::Files, CodeFormat::Pretty);
        let files = module.write_to_files_with_format(&directory, CodeFormat::Pretty);
        let Err(crate::Error::FormattingError(inline)) = inline else {
            panic!("Expected a formatting error for inline output");
        };
        let Err(crate::Error::FormattingError(files)) = files else {
            panic!("Expected a formatting error for file output");
        };
        assert_eq!(inline, files);
        #[cfg(not(feature = "pretty"))]
        assert_eq!(inline, "the pretty feature is not enabled");
        std::fs::remove_dir_all(directory).unwrap();
    }

    #[cfg(feature = "pretty")]
    #[test]
    fn pretty_format_produces_readable_source() {
        let mut module = Module::default();
        module.append(quote!(
            pub struct Example {
                pub value: u32,
            }
        ));
        let source = module
            .to_code_with_format(SubModules::Inline, CodeFormat::Pretty)
            .unwrap();
        assert_eq!(source, "pub struct Example {\n    pub value: u32,\n}\n");
    }

    #[test]
    fn formatted_writer_preserves_io_errors() {
        let module = Module::default();
        let error = module
            .write_to_files_with_format("", CodeFormat::Plain)
            .unwrap_err();
        assert!(
            matches!(error, crate::Error::IoError(ref error) if error.kind() == ErrorKind::NotFound)
        );
    }

    #[test]
    fn write_to_files_with_empty_directory_returns_error() {
        let module = Module::default();

        let err = module.write_to_files("").unwrap_err();

        assert_eq!(err.kind(), std::io::ErrorKind::NotFound);
    }
}
